def topo_sort(graph):
    # Build reverse graph for incoming edges
    incoming = {node: [] for node in graph}
    for node, prereqs in graph.items():
        for prereq in prereqs:
            incoming[prereq] = []
            incoming[prereq].append(node)

    # Build graph with incoming edges
    for node, prereqs in graph.items():
        for prereq in prereqs:
            if prereq not in incoming:
                incoming[prereq] = []
            for node in incoming[prereq]:
                if node not in graph:
                    graph[node] = []
                graph[node] = graph[node] + [prereq]

    # Build reverse graph with incoming edges
    reverse_graph = {node: [] for node in graph}
    for node, prereqs in graph.items():
        for prereq in prereqs:
            reverse_graph[prereq].append(node)

    # Build incoming edge count
    incoming_count = {node: 0 for node in graph}
    for node, prereqs in graph.items():
        for prereq in prereqs:
            incoming_count[prereq] += 1

    # Find nodes with no incoming edges (no prerequisites)
    ready = []
    for node in graph:
        if incoming_count[node] == 0:
            ready.append(node)

    # Sort lexicographically
    ready.sort()

    result = []
    while ready:
        # Get lexicographically smallest
        node = ready.pop(0)
        result.append(node)

        # Process outgoing edges
        for neighbor in graph[node]:
            incoming_count[neighbor] -= 1
            if incoming_count[neighbor] == 0:
                ready.append(neighbor)

    # Check for cycles
    if len(result) != len(graph):
        raise ValueError("Cycle detected")

    return result
